		; Uses two's complement: flip all bits then add 1
		sta P8ZP_SCRATCH_PTR
		sty P8ZP_SCRATCH_PTR+1

		ldy #$00
		lda (P8ZP_SCRATCH_PTR),y
		eor #$FF
		sta (P8ZP_SCRATCH_PTR),y
		iny

		lda (P8ZP_SCRATCH_PTR),y
		eor #$FF
		sta (P8ZP_SCRATCH_PTR),y
		iny

		lda (P8ZP_SCRATCH_PTR),y
		eor #$FF
		sta (P8ZP_SCRATCH_PTR),y
		iny

		lda (P8ZP_SCRATCH_PTR),y
		eor #$FF
		sta (P8ZP_SCRATCH_PTR),y

		; Add 1 to get two's complement (incrementing the 32-bit value)
